SetColumns(0);SetQuitOnError(true);SetMemoryLimit(8*10^9);SetSeed(20261026);tt:=Cputime();
load "C87/data/quotient33/plane_model_data.m";
load "C87/data/quotient33/canonical_data.m";
load "C87/data/quotient33/jmap_q_data.m";
K<t>:=FunctionField(GF(2));PF:=PolynomialRing(GF(2));RY<y>:=PolynomialRing(K);
function DecK(c)return (K!PF!c[1])/(K!PF!c[2]);end function;
f:=RY![DecK(c):c in AFPolynomialData];AF<g>:=FunctionField(f);assert Degree(AF) eq 31 and Genus(AF) eq 33;
function DecAF(cs)return &+[AF!DecK(cs[i])*g^(i-1):i in [1..#cs]];end function;
if AFBaseCoordinate eq 1 then uAF:=AF!t;vAF:=g;else uAF:=g;vAF:=AF!t;end if;
Z:=[DecAF(cs):cs in CanonicalCoordinateData];fv:=&+[uAF^e[1]*vAF^(e[2]-1):e in PlaneExponents|IsOdd(e[2])];assert fv ne 0;Z:=[fv*w:w in Z];DD:=LCM([Denominator(c):c in Eltseq(w),w in Z]);Z:=[AF!DD*w:w in Z];assert &and[Denominator(c) eq 1:c in Eltseq(w),w in Z];
printf "NONIC87_ADJOINT_COORDINATES_READY maxcoefdegree=%o time=%o\n",Max([Degree(Numerator(c)):c in Eltseq(w),w in Z]),Cputime(tt);
cz:=[Z[p[1]]*Z[p[2]]:p in pairs];assert &and[&+[v[i]*cz[i]:i in [1..561]] eq 0:v in Rows(QuadRelations)];
la:=&+[ProjectionRows[1,i]*Z[i]:i in [1..33]];assert (&+[ProjectionRows[2,i]*Z[i]:i in [1..33]])/la eq uAF and (&+[ProjectionRows[3,i]*Z[i]:i in [1..33]])/la eq vAF;
pows:=AssociativeArray();for i in [1..33] do pows[<i,0>]:=AF!1;for k in [1..9] do pows[<i,k>]:=pows[<i,k-1>]*Z[i];end for;end for;
ms:=[&*[pows[<i,e[i]>]:i in [1..33]]:e in Std9Exponents];j:=(&+[NumeratorVec[i]*ms[i]:i in [1..544]])/(&+[DenominatorVec[i]*ms[i]:i in [1..544]]);assert Degree(j) eq 480;cs:=Poles(j);
assert Sort([Degree(c):c in cs]) eq [1,1,1,1,2,2,4,4];cuspdata:=Sort([<Degree(c),-Valuation(j,c)>:c in cs]);assert cuspdata eq Sort([<1,1>^^4,<2,3>^^2,<4,29>,<4,87>]);
function CodeK(w)return <[Integers()!a:a in Eltseq(Numerator(w))],[Integers()!a:a in Eltseq(Denominator(w))]>;end function;
function CodeAF(w)return [CodeK(c):c in Eltseq(w)];end function;
PrintFile("C87/data/model_rebound_data.m",Sprintf("N:=87;genus:=33;AF_degree:=31;AFBaseCoordinate:=%o;AFPolynomialData:=%o;JFunctionData:=%o;CanonicalCoordinateData:=%o;Diamond2Matrix:=Matrix(GF(2),33,33,%o);",AFBaseCoordinate,AFPolynomialData,CodeAF(j),[CodeAF(w):w in Z],Eltseq(Diamond2Matrix)):Overwrite:=true);
printf "NONIC87_JMAP_AND_CUSPS_CERTIFIED jdegree480=true cusp_degree_width=%o time=%o\n",cuspdata,Cputime(tt);
load "C87/data/finite_j_model_snapshot.m";
assert AFPolynomialData eq [CodeK(c):c in Eltseq(DefiningPolynomial(AF))];assert JFunctionData eq CodeAF(j);assert CanonicalCoordinateData eq [CodeAF(w):w in Z];
print "NONIC87_FINITE_MODEL_SNAPSHOT_REBOUND_PASS genus33 jdegree480 canonical_quadrics465 inverse_projection=true snapshot_exact=true";quit;
